export const GAMES=new Set(['runner','jet']);
const json=(data,status=200,extra={})=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff',...extra}});
export function validateResult(v,run,now){if(!v||!Number.isSafeInteger(v.score)||v.score<0||!Number.isFinite(v.duration)||v.duration<0||v.duration>91||!Number.isFinite(v.distance)||v.distance<0)return false;const elapsed=(now-run.started_at)/1000;if(v.duration>elapsed+4||elapsed>86400)return false;if(run.game==='runner')return v.distance<=v.duration*31+8&&v.score<=v.distance*2+Math.ceil(v.duration*35)+50;return v.distance<=v.duration*1100+100&&v.score<=v.duration*1500+100;}
function visitor(request){return request.headers.get('cookie')?.match(/(?:^|; *)arcade_visitor=([a-f0-9-]{36})(?:;|$)/)?.[1]||null}
export async function api(request,env){const u=new URL(request.url),db=env.DB;if(!db)return json({error:'排行榜暫時未連線，遊戲仍可繼續。'},503);if(['POST','DELETE'].includes(request.method)&&request.headers.get('origin')!==u.origin)return json({error:'Invalid origin'},403);
try{if(request.method==='GET'&&u.pathname==='/api/leaderboard'){const game=u.searchParams.get('game');if(!GAMES.has(game))return json({error:'Unknown game'},400);const recent=u.searchParams.get('view')==='recent',order=recent?'finished_at DESC':'score DESC, finished_at ASC';const rows=await db.prepare('SELECT id,player,score,distance,duration,difficulty,finished_at FROM arcade_runs WHERE game=? AND finished_at IS NOT NULL ORDER BY '+order+' LIMIT 30').bind(game).all();return json({entries:rows.results||[],shared:true,game})}
if(request.method==='DELETE'&&u.pathname==='/api/runs/mine'){const who=visitor(request);if(!who)return json({deleted:0});const r=await db.prepare('DELETE FROM arcade_runs WHERE visitor=?').bind(who).run();return json({deleted:r.meta.changes})}if(request.method!=='POST')return json({error:'Not found'},404);if(!request.headers.get('content-type')?.startsWith('application/json'))return json({error:'JSON required'},415);const raw=await request.text();if(raw.length>2048)return json({error:'Request too large'},413);let body;try{body=JSON.parse(raw)}catch{return json({error:'Invalid JSON'},400)}const now=Date.now();
if(u.pathname==='/api/runs/start'){if(!GAMES.has(body.game))return json({error:'Unknown game'},400);const id=crypto.randomUUID(),who=visitor(request)||crypto.randomUUID();const rate=await db.prepare('SELECT COUNT(*) AS n FROM arcade_runs WHERE visitor=? AND started_at>?').bind(who,now-60000).first();if(rate.n>=12)return json({error:'稍等一陣，再開新一局。'},429);const player=String(body.player||'玩家').normalize('NFKC').replace(/[<>\x00-\x1f]/g,'').trim().slice(0,20)||'玩家';const difficulty=['easy','medium','hard','standard'].includes(body.difficulty)?body.difficulty:'standard';await db.prepare('INSERT INTO arcade_runs(id,game,player,visitor,started_at,difficulty) VALUES(?,?,?,?,?,?)').bind(id,body.game,player,who,now,difficulty).run();return json({id},201,{'set-cookie':'arcade_visitor='+who+'; Path=/; HttpOnly; SameSite=Strict; Max-Age=31536000'+(u.protocol==='https:'?'; Secure':'')})}
if(u.pathname==='/api/runs/finish'){if(typeof body.id!=='string'||body.id.length>40)return json({error:'Invalid run'},400);const run=await db.prepare('SELECT * FROM arcade_runs WHERE id=? AND visitor=?').bind(body.id,visitor(request)||'').first();if(!run)return json({error:'Unknown run'},404);if(run.finished_at!==null)return json({saved:true,duplicate:true,id:run.id});if(!validateResult(body,run,now))return json({error:'成績未能通過檢查。'},400);const result=await db.prepare('UPDATE arcade_runs SET finished_at=?,score=?,distance=?,duration=? WHERE id=? AND finished_at IS NULL').bind(now,body.score,Math.floor(body.distance),Math.round(body.duration*1000),run.id).run();return json({saved:true,id:run.id,duplicate:!result.meta.changes})}return json({error:'Not found'},404)}catch(e){console.error('Leaderboard request failed',String(e));return json({error:'排行榜暫時未能載入，請稍後再試。'},503)}}
export default{async fetch(request,env){if(new URL(request.url).pathname.startsWith('/api/'))return api(request,env);return env.ASSETS.fetch(request)}};
